// ACC-009 private-stage V15 successor; owner Apply is NOT released.

/** ACC-009-H1, PHP8.0. Owner-only execution; no app bootstrap, DB mutation,
 * sender/queue repair/replay or cache cleanup. C1 must be applied before H1.
 * --dry-run: exact sources, C1 phase, read-only schema/events and real web runtime.
 * --apply: repeat admission, backup, helper -> Telegram -> model, native lint.
 * --rollback=<backup-basename>: reverse order, only exact after hashes; no SQL.
 * Source rollback cannot undo orders, queued work or remote effects.
 * Delivery/concurrency limitations are stated in the implementation report.
 */
const H1_SPEC='';
const H1_HELPER='';

// Pure, pinned-source edit recipes. This file never loads application/config code.
function h1_check(bool $ok, string $code): void {
    if (!$ok) {
        throw new \RuntimeException($code);
    }
}

/** Token offsets are byte offsets, independent of platform newline rendering. */
function h1_tokens(string $source): array {
    $out = []; $offset = 0;
    foreach (token_get_all($source) as $token) {
        $text = is_array($token) ? $token[1] : $token;
        $out[] = ['id' => is_array($token) ? $token[0] : null, 'text' => $text, 'start' => $offset, 'end' => $offset + strlen($text)];
        $offset += strlen($text);
    }
    return $out;
}

function h1_eol(string $source, string $newText): string {
    return strpos($source, "\r\n") !== false ? str_replace("\n", "\r\n", $newText) : $newText;
}

function h1_method(string $source, string $name): array {
    $tokens = h1_tokens($source); $matches = [];
    foreach ($tokens as $i => $token) {
        if ($token['id'] !== T_FUNCTION) continue;
        $j = $i + 1;
        while (isset($tokens[$j]) && in_array($tokens[$j]['id'], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT], true)) $j++;
        if (!isset($tokens[$j]) || $tokens[$j]['id'] !== T_STRING || $tokens[$j]['text'] !== $name) continue;
        $brace = $j;
        while (isset($tokens[$brace]) && $tokens[$brace]['text'] !== '{') $brace++;
        h1_check(isset($tokens[$brace]), 'method_body_missing');
        $depth = 1; $end = $brace + 1;
        for (; isset($tokens[$end]); $end++) {
            if (($tokens[$end]['id'] === null && $tokens[$end]['text'] === '{') || in_array($tokens[$end]['id'], [T_CURLY_OPEN, T_DOLLAR_OPEN_CURLY_BRACES], true)) $depth++;
            if ($tokens[$end]['id'] === null && $tokens[$end]['text'] === '}' && --$depth === 0) break;
        }
        h1_check(isset($tokens[$end]), 'method_braces');
        $matches[] = ['start' => $token['start'], 'body' => $tokens[$brace]['end'], 'end' => $tokens[$end]['end']];
    }
    h1_check(count($matches) === 1, 'method_not_unique');
    return $matches[0];
}

function h1_once(string $source, string $old, string $new): string {
    h1_check(substr_count($source, $old) === 1, 'anchor_not_unique');
    return str_replace($old, $new, $source);
}

/** Locate the complete call without inspecting/disclosing its opaque literal. */
function h1_call(string $method, string $prefix): array {
    h1_check(substr_count($method, $prefix) === 1, 'call_not_unique');
    $start = strpos($method, $prefix);
    $tokens = h1_tokens("<?php " . substr($method, $start));
    $opened = false; $depth = 0; $close = null; $end = null;
    foreach ($tokens as $token) {
        if ($token['id'] !== null) continue;
        if ($token['text'] === '(') { $opened = true; $depth++; }
        if ($token['text'] === ')' && $opened && --$depth === 0) $close = $token['start'] - 6;
        if ($close !== null && $token['text'] === ';') { $end = $token['end'] - 6; break; }
    }
    h1_check($close !== null && $end !== null, 'call_shape');
    return ['start' => $start, 'close' => $start + $close, 'end' => $start + $end];
}

function h1_edit_method(string $source, string $name, callable $edit): string {
    $bounds = h1_method($source, $name);
    $old = substr($source, $bounds['start'], $bounds['end'] - $bounds['start']);
    $new = $edit($old);
    return substr_replace($source, $new, $bounds['start'], strlen($old));
}

function h1_guard_load(): string {
    return <<<'PHP'
$acc009_h1_file = DIR_SYSTEM . 'library/booster_order_notification_guard.php';
if (!is_file($acc009_h1_file)) {
    throw new \RuntimeException('ACC009_H1_HELPER_UNAVAILABLE');
}
require_once($acc009_h1_file);
PHP;
}

