        return substr_replace($method, h1_eol($method, $replacement), $call['start'], $ncrm['end'] - $call['start']);
    });
    foreach (['boosterCrmSync', 'ncrmOrderSync'] as $name) {
        $source = h1_edit_method($source, $name, static function (string $method) use ($name): string {
            $method = h1_once($method, 'string $event): void', 'string $event, ?int $order_history_id = null, ?int $void_status_id = null): void');
            $method = h1_once($method, 'use ($order_id, $event)', 'use ($order_id, $event, $order_history_id, $void_status_id)');
