function h1_transform_telegram(string $source): string {
    return h1_edit_method($source, 'sendOrderNotification', static function (string $method): string {
        $method = h1_once($method, 'int $new_status_id): void', 'int $new_status_id, ?int $order_history_id = null, ?int $void_status_id = null): void');
        $query = h1_call($method, '$this->db->query(');
        $start = strrpos(substr($method, 0, $query['start']), '$query =');
        h1_check($start !== false, 'telegram_query_assignment');
        $tokens = h1_tokens("<?php " . substr($method, $query['end']));
        $opening = false; $depth = 0; $finish = null;
        foreach ($tokens as $token) {
            if ($token['id'] !== null) continue;
            if ($token['text'] === '{') { $opening = true; $depth++; }
            if ($opening && $token['text'] === '}' && --$depth === 0) { $finish = $query['end'] + $token['end'] - 6; break; }
        }
        h1_check($finish !== null, 'telegram_legacy_guard');
        $legacy = substr($method, $start, $finish - $start);
        $replacement = h1_eol($method, "// ACC-009-H1-TELEGRAM-HISTORY-ID\nif (\$order_history_id === null) {\n") . $legacy . h1_eol($method, "\n} else {\n");
        $newGuard = "try {\n" . h1_guard_load() . <<<'PHP'

$acc009_h1_decision = \Opencart\System\Library\BoosterOrderNotificationGuard::classify($this->db, (int)$order_id, $order_history_id, (int)($void_status_id ?? 0));
if ($acc009_h1_decision['state'] !== 'first') { return; }
} catch (\Throwable $acc009_h1_error) {
    error_log('ACC-009-H1 telegram-unavailable order_id=' . (int)$order_id);
    return;
}
}
// ACC-009-H1-TELEGRAM-HISTORY-ID-END
PHP;
        $replacement .= h1_eol($method, $newGuard);
        $changed = substr_replace($method, $replacement, $start, $finish - $start);
        h1_check(substr_count($changed, $legacy) === 1, 'legacy_bytes_preserved');
        return $changed;
    });
}


class Acc009AdmissionFailure extends RuntimeException {}
function acc009a_fail(string $code): void { throw new Acc009AdmissionFailure($code); }
function acc009a_config_literals(string $code): array {
    if (!function_exists('token_get_all') || strlen($code) > 524288) acc009a_fail('config_parser_unavailable_or_size_cap');
    $tokens = array_values(array_filter(token_get_all($code), static function($t) {
        return !is_array($t) || !in_array($t[0], [T_WHITESPACE,T_COMMENT,T_DOC_COMMENT], true);
    }));
    if (!isset($tokens[0]) || !is_array($tokens[0]) || $tokens[0][0] !== T_OPEN_TAG) acc009a_fail('config_literal_grammar_required');
    $values = []; $count = count($tokens); $storedBytes=0;
    for ($i = 1; $i < $count;) {
        $t = $tokens[$i];
        if (is_array($t) && $t[0] === T_CLOSE_TAG && $i === $count - 1) break;
        if (!is_array($t) || !in_array(strtolower($t[1]), ['define','\\define'], true)
            || !in_array($t[0], [T_STRING,T_NAME_FULLY_QUALIFIED], true)
            || ($tokens[$i+1] ?? null) !== '(' || !is_array($tokens[$i+2] ?? null)
            || $tokens[$i+2][0] !== T_CONSTANT_ENCAPSED_STRING || ($tokens[$i+3] ?? null) !== ',') acc009a_fail('config_literal_grammar_required');
        $name = acc009a_config_string($tokens[$i+2][1]);
        if (!preg_match('/^[A-Z][A-Z0-9_]*$/D', $name) || array_key_exists($name, $values)) acc009a_fail('config_duplicate_or_indirect_definition');
        $j=$i+4; $value='';
        while (true) {
            $operand=$tokens[$j]??null;
            if (!is_array($operand)) acc009a_fail('config_literal_grammar_required');
            if ($operand[0]===T_CONSTANT_ENCAPSED_STRING) $piece=acc009a_config_string($operand[1]);
            elseif ($operand[0]===T_LNUMBER && preg_match('/^(?:0|[1-9][0-9]*)$/D',$operand[1])) $piece=$operand[1];
            elseif ($operand[0]===T_STRING && array_key_exists($operand[1],$values)) $piece=$values[$operand[1]];
            else acc009a_fail('config_unknown_or_unsafe_operand');
            if (strlen($value)+strlen($piece)>524288) acc009a_fail('config_evaluated_value_size_cap');
            $value.=$piece; $j++;
            if (($tokens[$j]??null)==='.') { $j++; continue; }
            if (($tokens[$j]??null)!==')'||($tokens[$j+1]??null)!==';') acc009a_fail('config_literal_grammar_required');
            break;
        }
        $storedBytes+=strlen($value);
        if ($storedBytes>2097152) acc009a_fail('config_aggregate_value_size_cap');
        $values[$name]=$value; $i=$j+2;
    }
    return $values;
}
function acc009a_config_string(string $literal): string {
    if (strlen($literal)<2 || !in_array($literal[0],["'",'"'],true) || substr($literal,-1)!==$literal[0]) acc009a_fail('config_binary_or_invalid_string_literal');
    $value = substr($literal, 1, -1);
    if ($literal[0] === "'") return str_replace(["\\'",'\\\\'], ["'",'\\'], $value);
    // Double-quoted strings with escapes/interpolation require explicit review.
    if (strpos($value, '\\') !== false || strpos($value, '$') !== false) acc009a_fail('config_escaped_double_quote_requires_review');
    return $value;
}

function acc009a_path(string $root, string $relative): string {
    if (!preg_match('~^[A-Za-z0-9_./-]+$~D', $relative) || strpos($relative, '..') !== false || $relative[0] === '/') acc009a_fail('unsafe_relative_path');
    $path = $root;
    foreach (explode('/', $relative) as $part) {
        $path .= '/' . $part;
        if (is_link($path)) acc009a_fail('linked_source_or_config');
    }
    return $path;
}
function acc009a_config(string $root): array {
    $configs = [];
    foreach (['catalog'=>'config.php', 'admin'=>'adminEvhenii/config.php'] as $app=>$relative) {
        $path = acc009a_path($root, $relative);
        if (!is_file($path) || filesize($path)>524288) acc009a_fail('hosting_config_missing_or_size_cap');
        $body = file_get_contents($path);
        if (!is_string($body)) acc009a_fail('hosting_config_unreadable');
        $v = acc009a_config_literals($body); unset($body);
        foreach (['DB_HOSTNAME','DB_PORT','DB_DATABASE','DB_PREFIX','DB_DRIVER','DB_USERNAME','DB_PASSWORD','DIR_OPENCART','DIR_APPLICATION','DIR_SYSTEM','DIR_EXTENSION','DIR_CONFIG','DIR_TEMPLATE','APPLICATION'] as $key) {
            if (!array_key_exists($key,$v)) acc009a_fail('hosting_config_incomplete');
        }
        if ($v['APPLICATION'] !== ($app==='admin'?'Admin':'Catalog') || $v['DB_DRIVER']!=='mysqli'
            || stripos($v['DB_HOSTNAME'],'p:')===0 || !preg_match('/^[1-9][0-9]{0,4}$/D',$v['DB_PORT'])
            || (int)$v['DB_PORT']>65535 || !preg_match('/^[A-Za-z0-9_]+$/D',$v['DB_PREFIX'])) acc009a_fail('config_target_not_admitted');
        foreach (['DIR_OPENCART'=>'','DIR_APPLICATION'=>($app==='admin'?'adminEvhenii':'catalog'),'DIR_SYSTEM'=>'system','DIR_EXTENSION'=>'extension','DIR_CONFIG'=>'system/config','DIR_TEMPLATE'=>($app==='admin'?'adminEvhenii':'catalog').'/view/template'] as $key=>$relativePath) {
            $wanted = $relativePath===''?$root:acc009a_path($root,$relativePath);
            if (realpath($v[$key])===false || realpath($wanted)===false || realpath($v[$key])!==realpath($wanted)) acc009a_fail('configured_runtime_path_mismatch');
        }
        $configs[$app]=$v;
    }
    foreach (['DB_HOSTNAME','DB_PORT','DB_DATABASE','DB_PREFIX','DB_DRIVER'] as $key) {
        if ($configs['catalog'][$key]!==$configs['admin'][$key]) acc009a_fail('catalog_admin_db_target_mismatch');
    }
    return $configs['admin'];
}
function acc009a_rows(mysqli $db, string $sql, int $cap=128): array {
    if (strpos($sql,'SELECT ')!==0 || strpos($sql,';')!==false || $cap<1 || $cap>512) acc009a_fail('read_only_query_guard');
    $statement=$db->prepare($sql);
    if (!$statement) acc009a_fail('metadata_prepare_failed');
    try {
        if (!$statement->execute()) acc009a_fail('metadata_execute_failed');
        $meta=$statement->result_metadata();
        if (!$meta) acc009a_fail('metadata_result_missing');
        $bound=[]; $refs=[];
        foreach ($meta->fetch_fields() as $column) { $bound[$column->name]=null; $refs[]=&$bound[$column->name]; }
        $meta->free();
        if (!$statement->bind_result(...$refs)) acc009a_fail('metadata_bind_failed');
        $rows=[];
        while (($fetch=$statement->fetch())===true) {
            $row=[]; foreach ($bound as $key=>$value) $row[$key]=$value;
            $rows[]=$row;
            if (count($rows)>$cap) acc009a_fail('metadata_result_cap');
        }
        if ($fetch===false || $statement->errno) acc009a_fail('metadata_fetch_failed');
        return $rows;
    } finally { $statement->close(); }
}


function h1_hash(string $path): ?string {
    if (!file_exists($path)) return null;
    if (!is_file($path) || filesize($path)>4000000) acc009a_fail('source_type_or_size_cap');
    $hash=hash_file('sha256',$path);if (!is_string($hash)) acc009a_fail('source_hash_failed');return $hash;
}
function h1_event_matches(string $trigger,string $target): bool {
    // Exact prefix/wildcard semantics of the pinned native Event::trigger.
    return preg_match('~^'.str_replace(['\\*','\\?'],['.*','.'],preg_quote($trigger,'~')).'~',$target)===1;
}

// Current owner capture: one store, canonical void15, nine normalized status pins.
// Additional status-setting families used by pinned Hutko/PUMB source are collision
// checks only; their exact non-void values are not inferred from the narrow capture.
function h1_void_contract(mysqli $db,array $config,array $spec): array {
    $prefix=$config['DB_PREFIX'];
    $stores=acc009a_rows($db,'SELECT store_id FROM `'.$prefix.'store` ORDER BY store_id LIMIT 65',64);
    if($stores!==[])acc009a_fail('configured_store_inventory_changed_requires_review');
    $rows=acc009a_rows($db,'SELECT store_id, `key`, value, serialized FROM `'.$prefix.'setting` WHERE `key` IN (\'config_void_status_id\',\'config_order_status_id\',\'config_processing_status\',\'config_complete_status\',\'config_fraud_status_id\') OR `key` REGEXP \'^(payment|total)_[A-Za-z0-9_]+_order_status(_[A-Za-z0-9]+)*_id$\' ORDER BY store_id, `key` LIMIT 257',256);
    $normalized=[];
    foreach($rows as $row){
        if((string)$row['store_id']!=='0'||!is_string($row['key'])||!is_string($row['value'])||strlen($row['value'])>4096||!in_array((string)$row['serialized'],['0','1'],true))acc009a_fail('status_setting_shape_changed');
        $raw=$row['value'];$ids=[];$shape='canonical_integer';
        if((string)$row['serialized']==='0'){
            if(!preg_match('/^(?:0|[1-9][0-9]{0,9})$/D',$raw)||(float)$raw>2147483647)acc009a_fail('canonical_status_scalar_required');$ids=[(int)$raw];
        }else{
            try{$values=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(Throwable $e){acc009a_fail('canonical_status_list_required');}
            if(!is_array($values)||count($values)>64||($values!==[]&&array_keys($values)!==range(0,count($values)-1))||($values===[]&&trim($raw)!=='[]'))acc009a_fail('canonical_status_list_required');
            foreach($values as $id){if((!is_int($id)&&!is_string($id))||!preg_match('/^(?:0|[1-9][0-9]{0,9})$/D',(string)$id)||(float)$id>2147483647)acc009a_fail('canonical_status_list_required');$ids[]=(int)$id;}
            $shape='json_integer_list';
        }
        $normalized[]=['store_id'=>0,'key'=>$row['key'],'serialized'=>(int)$row['serialized'],'shape'=>$shape,'ids'=>$ids];
    }
    if(($spec['void_contract']['configured_store_ids']??null)!==[0]||($spec['void_contract']['void_status_id']??null)!==15||$normalized!==($spec['void_contract']['status_settings']??null))acc009a_fail('void_or_pinned_status_settings_changed_requires_review');
    foreach($normalized as $row){if($row['key']!=='config_void_status_id'&&in_array(15,$row['ids'],true))acc009a_fail('void_status_collision_requires_owner_decision');}
    $additional=acc009a_rows($db,'SELECT store_id, `key`, value, serialized FROM `'.$prefix.'setting` WHERE `key` IN (\'payment_hutko_success_status_id\',\'payment_hutko_declined_status_id\',\'payment_hutko_expired_status_id\') OR `key` REGEXP \'^payment_pumb_credit_status_[A-Za-z0-9_]+$\' ORDER BY store_id, `key` LIMIT 129',128);
    $seen=[];
    foreach($additional as $row){
        if((string)$row['store_id']!=='0'||!is_string($row['key'])||strlen($row['key'])>128||((!in_array($row['key'],['payment_hutko_success_status_id','payment_hutko_declined_status_id','payment_hutko_expired_status_id'],true))&&!preg_match('/^payment_pumb_credit_status_[A-Za-z0-9_]+$/D',$row['key']))||isset($seen[$row['key']])||!is_string($row['value'])||(string)$row['serialized']!=='0'||!preg_match('/^(?:0|[1-9][0-9]{0,9})$/D',$row['value'])||(float)$row['value']>2147483647)acc009a_fail('additional_payment_status_shape_requires_review');
        $seen[$row['key']]=true;
        if((int)$row['value']===15)acc009a_fail('void_additional_payment_status_collision_requires_owner_decision');
    }
    return ['void_status'=>'canonical_15_single_store_pinned','configured_void_status_id'=>15,'pinned_status_settings'=>count($normalized),'additional_payment_status_keys_checked'=>count($additional),'status_scope'=>'captured_nine_plus_pinned_Hutko_PUMB_setting_families_not_universal_custom_status_or_historical_config_proof'];
}

function h1_metadata(mysqli $db,array $config,array $spec): array {
