            b_check_restore_authority($path,$meta);
            $file=$dir.'/'.$i.'.source';if(file_put_contents($file,$body,LOCK_EX)!==strlen($body)||!chmod($file,0600)||hash_file('sha256',$file)!==$row['before'])acc009a_fail('backup_verification');
        }
        $saved[$i]=['body'=>$body,'stat'=>$meta];$manifest['files'][]=$row+['stat'=>$meta];
    }
    $json=json_encode($manifest,JSON_THROW_ON_ERROR);if(file_put_contents($dir.'/manifest.json',$json,LOCK_EX)!==strlen($json)||!chmod($dir.'/manifest.json',0600))acc009a_fail('backup_manifest');
    $written=[];
    try{
        foreach($spec['files'] as $i=>$row){
            if($i===($spec['c1_count']??-1))b_composition_barrier($root,$spec);
            $path=acc009a_path($root,$row['relative']);if(h1_hash($path)!==$row['before'])acc009a_fail('concurrent_target_change');
            $m=$saved[$i]['stat'];if($m!==null&&b_stat($path)!==$m)acc009a_fail('concurrent_target_metadata_change');
            $written[]=$i;h1_replace($path,$payloads[$i],$m['mode']??0644,$m['uid']??null,$m['gid']??null);
            if(substr($row['relative'],-4)==='.php')h1_lint($path);
            if(h1_hash($path)!==$row['after']||($m!==null&&b_stat($path)!==$m))acc009a_fail('after_hash_or_metadata');
            b_receipt($row,$row['before']===null?'none':$dir.'/'.$i.'.source',substr($row['relative'],-4)==='.php'?'php_lint_ok':'not_php','applied',1,$row['before'],$row['after']);
        }
    }catch(Throwable $error){
