            if($actual===$row['before'])continue;
            if($actual!==$row['after'])acc009a_fail('restore_conflict_backup_retained');
            $m=$saved[$i]['stat'];
            if($saved[$i]['body']===null){if(!unlink($path))acc009a_fail('created_file_restore_failed');}
            else{h1_replace($path,$saved[$i]['body'],$m['mode'],$m['uid'],$m['gid']);if(substr($row['relative'],-4)==='.php')h1_lint($path);}
            if(h1_hash($path)!==$row['before'])acc009a_fail('restored_hash_failed');
