function b_manifest_row(array $specRow,array $manifestRow): ?array {
    $meta=$manifestRow['stat']??null;unset($manifestRow['stat']);
    if($manifestRow!==$specRow)acc009a_fail('backup_manifest_row');
    if($specRow['before']===null){if($meta!==null)acc009a_fail('created_file_backup_metadata');return null;}
    if(!is_array($meta)||array_keys($meta)!==['mode','uid','gid']||!is_int($meta['mode'])||$meta['mode']<0||$meta['mode']>0777||!is_int($meta['uid'])||$meta['uid']<0||!is_int($meta['gid'])||$meta['gid']<0)acc009a_fail('backup_manifest_metadata');
    return $meta;
}
function h1_rollback(string $root,array $spec,string $name): void {
    if(!preg_match('/^ACC-009-C1-H1-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}$/D',$name))acc009a_fail('backup_name');
    $dir=h1_backup_base($root).'/'.$name;
    if(is_link($dir)||!is_dir($dir)||is_link($dir.'/manifest.json')||!is_file($dir.'/manifest.json')||filesize($dir.'/manifest.json')>32768)acc009a_fail('backup_path_or_manifest');
    $manifest=json_decode(file_get_contents($dir.'/manifest.json'),true,32,JSON_THROW_ON_ERROR);
    if(($manifest['id']??null)!=='ACC-009-C1-H1'||($manifest['format']??null)!==2||count($manifest['files']??[])!==count($spec['files']))acc009a_fail('backup_manifest_identity');
    $saved=[];$afterimages=[];$current=[];
    // Complete classification and backup/ownership preflight BEFORE the first write.
    foreach($spec['files'] as $i=>$row){
        $meta=b_manifest_row($row,$manifest['files'][$i]);$path=acc009a_path($root,$row['relative']);$actual=h1_hash($path);
        if($actual!==$row['before']&&$actual!==$row['after'])acc009a_fail('rollback_target_changed');
        $current[$i]=$actual;$saved[$i]=['body'=>null,'stat'=>$meta];
        if($actual===$row['before'])continue;
        $body=file_get_contents($path);if(!is_string($body)||hash('sha256',$body)!==$row['after'])acc009a_fail('rollback_afterimage_changed');
        $afterimages[$i]=['body'=>$body,'stat'=>b_stat($path)];
        if($meta!==null){
            if($afterimages[$i]['stat']!==$meta)acc009a_fail('rollback_after_metadata_changed');
            $backup=$dir.'/'.$i.'.source';if(is_link($backup)||!is_file($backup)||filesize($backup)>4000000||hash_file('sha256',$backup)!==$row['before'])acc009a_fail('backup_source_identity');
            $original=file_get_contents($backup);if(!is_string($original)||hash('sha256',$original)!==$row['before'])acc009a_fail('backup_changed_during_read');
            if(substr($row['relative'],-4)==='.php')h1_lint_body($original);
            b_check_restore_authority($path,$meta);$saved[$i]['body']=$original;
        }
    }
    h1_log('rollback_preflight','all_targets_and_required_backups_verified');h1_log('backup_path',$dir);$written=[];
    try{
        foreach(array_reverse(array_keys($spec['files'])) as $i){
            $row=$spec['files'][$i];$path=acc009a_path($root,$row['relative']);$actual=h1_hash($path);
            if($actual!==$current[$i])acc009a_fail('rollback_concurrent_change');
            if($actual===$row['before']){b_receipt($row,'none','not_written','already_before',0,$actual,$actual);continue;}
            if(b_stat($path)!==$afterimages[$i]['stat'])acc009a_fail('rollback_concurrent_metadata_change');
            $m=$saved[$i]['stat'];$written[]=$i;
            if($m===null){if(!unlink($path))acc009a_fail('rollback_created_file_remove');}
            else{h1_replace($path,$saved[$i]['body'],$m['mode'],$m['uid'],$m['gid']);if(substr($row['relative'],-4)==='.php')h1_lint($path);}
            if(h1_hash($path)!==$row['before']||($m!==null&&b_stat($path)!==$m))acc009a_fail('rollback_hash_or_metadata');
            b_receipt($row,$m===null?'none':$dir.'/'.$i.'.source',$m!==null&&substr($row['relative'],-4)==='.php'?'php_lint_ok':'not_php','restored',1,$actual,$row['before']);
        }
    }catch(Throwable $error){
        foreach(array_reverse($written) as $i){
            $row=$spec['files'][$i];$path=acc009a_path($root,$row['relative']);$actual=h1_hash($path);
            if($actual===$row['after'])continue;
            if($actual!==$row['before'])acc009a_fail('rollback_restore_conflict');
            $m=$afterimages[$i]['stat'];h1_replace($path,$afterimages[$i]['body'],$m['mode'],$m['uid'],$m['gid']);
            if(substr($row['relative'],-4)==='.php')h1_lint($path);
            if(h1_hash($path)!==$row['after'])acc009a_fail('rollback_restore_hash');
        }
        acc009a_fail('rollback_failed_prior_mixed_state_restored');
    }
    foreach($spec['files'] as $row)if(h1_hash(acc009a_path($root,$row['relative']))!==$row['before'])acc009a_fail('rollback_final_set_drift');
    h1_log('rollback','ok');h1_log('host_php_lint','ok');
}
function b_probe_create(string $root,string $nonce,string $runnerSha): array {
    if(!preg_match('/^[a-f0-9]{32}$/D',$nonce)||!preg_match('/^[a-f0-9]{64}$/D',$runnerSha))acc009a_fail('probe_identity_shape');
    $name='ACC-009-C1-H1-runtime-'.$nonce.'.php';$path=$root.'/'.$name;
    $body="<?php\n".'$nonce='.var_export($nonce,true).';' . "\n".
        'if(($_SERVER[\'REQUEST_METHOD\']??\'\')!==\'GET\'||($_GET[\'acc009_h1_probe\']??null)!==$nonce||!hash_equals($nonce,(string)($_SERVER[\'HTTP_X_ACC009_SEAL\']??\'\'))){http_response_code(404);exit;}' . "\n".
        'header(\'Content-Type: application/json; charset=utf-8\');header(\'Cache-Control: no-store, max-age=0\');header(\'X-Content-Type-Options: nosniff\');header(\'X-ACC009-Seal: \'.$nonce);' . "\n".
        '$runtime=[\'php_version\'=>PHP_VERSION,\'sapi\'=>PHP_SAPI,\'opcache\'=>[\'enabled\'=>ini_get(\'opcache.enable\')===\'1\',\'validate_timestamps\'=>ini_get(\'opcache.validate_timestamps\')===\'1\',\'revalidate_freq\'=>(int)ini_get(\'opcache.revalidate_freq\')],\'auto_prepend_file_empty\'=>ini_get(\'auto_prepend_file\')===\'\',\'auto_append_file_empty\'=>ini_get(\'auto_append_file\')===\'\'];' . "\n".
        'echo json_encode([\'task\'=>\'ACC-009-H1-web-runtime\',\'probe_nonce\'=>$nonce,\'runner_sha256\'=>'.var_export($runnerSha,true).',\'runtime\'=>$runtime,\'seal_request_matches\'=>true],JSON_THROW_ON_ERROR);' . "\n";
    h1_lint_body($body);$handle=@fopen($path,'xb');if($handle===false)acc009a_fail('probe_exclusive_create');
    $identity=fstat($handle);
    try{
        if(fwrite($handle,$body)!==strlen($body)||!chmod($path,0644)||h1_hash($path)!==hash('sha256',$body))acc009a_fail('probe_write_or_identity');
    }catch(Throwable $error){
        $current=is_link($path)?false:lstat($path);
        if(!is_array($current)||$current['ino']!==$identity['ino']||$current['dev']!==$identity['dev'])acc009a_fail('partial_probe_cleanup_conflict');
        if(!unlink($path))acc009a_fail('partial_probe_cleanup_failed');
        throw $error;
    }finally{fclose($handle);}
    $probe=['path'=>$path,'name'=>$name,'sha256'=>hash('sha256',$body)];
    h1_log('web_probe_path',$path);h1_log('web_probe_sha256',$probe['sha256']);return $probe;
}
function b_probe_cleanup(array $probe): void {
    if(h1_hash($probe['path'])!==$probe['sha256'])acc009a_fail('probe_cleanup_conflict_do_not_delete_unknown_bytes');
    if(!unlink($probe['path']))acc009a_fail('probe_cleanup_failed');
    h1_log('web_probe_cleanup','ok');
}
function b_web(string $root): array {
    $nonce=bin2hex(random_bytes(16));$runnerSha=hash_file('sha256',__FILE__);$probe=b_probe_create($root,$nonce,$runnerSha);
    try{
        $url='https://boostershop.website/'.$probe['name'].'?acc009_h1_probe='.$nonce;
        $context=stream_context_create(['http'=>['method'=>'GET','header'=>'X-ACC009-Seal: '.$nonce."\r\n",'timeout'=>15,'follow_location'=>0,'ignore_errors'=>true],'ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'allow_self_signed'=>false]]);
        $body=file_get_contents($url,false,$context,0,16385);
        if(!is_string($body)||strlen($body)>16384||!isset($http_response_header[0])||!preg_match('~^HTTP/[0-9.]+ 200(?: |$)~D',$http_response_header[0]))acc009a_fail('web_probe_failed');
        $data=json_decode($body,true,16,JSON_THROW_ON_ERROR);$runtime=h1_validate_web($data,$nonce,$runnerSha);b_validate_seal($data,$http_response_header,$nonce);
        return $runtime;
    }finally{b_probe_cleanup($probe);}
}

